#!/usr/bin/env python3
"""
M3.75 Apply Script - Run from your malaga_local_app_v1 project root.
Overwrites: app.py, core/db.py, core/policy.py, features/explain_engine.py
Usage: python apply_m375.py
"""
import base64, tarfile, io

DATA = """

"""

print("Applying M3.75: Policy-as-Code + Audit Events + Middleware")
print("=" * 70)

buf = io.BytesIO(base64.b64decode(DATA))
with tarfile.open(fileobj=buf, mode="r:gz") as tar:
    for member in tar.getmembers():
        print(f"  Writing: {member.name}")
        tar.extract(member, path=".", filter="data")

print("=" * 70)
print("Done! Verify: python -c \"import app; print('OK')\"")
